-- Close client-side privilege gaps found during the pre-demo security audit.

-- Public buckets already allow retrieval through public object URLs. A SELECT
-- policy is unnecessary and also lets clients enumerate every stored filename.
DROP POLICY IF EXISTS "Event images are publicly readable" ON storage.objects;
DROP POLICY IF EXISTS "Quest images are publicly readable" ON storage.objects;

-- Users may only acknowledge their own notifications. Notification content is
-- generated by trusted database functions and must not be client-editable.
REVOKE UPDATE ON TABLE public.user_notifications FROM authenticated;
GRANT UPDATE (read_at) ON TABLE public.user_notifications TO authenticated;

-- RSVP clients can express intent, but only the QR-validated SECURITY DEFINER
-- RPC may create an attended response.
DROP POLICY IF EXISTS "Users manage their own event responses"
  ON public.user_event_responses;

CREATE POLICY "Users view their own event responses"
  ON public.user_event_responses FOR SELECT TO authenticated
  USING (user_id = (SELECT auth.uid()));

CREATE POLICY "Users create RSVP responses for approved events"
  ON public.user_event_responses FOR INSERT TO authenticated
  WITH CHECK (
    user_id = (SELECT auth.uid())
    AND status IN ('interested', 'going')
    AND EXISTS (
      SELECT 1
      FROM public.organizer_events AS event
      WHERE event.id = event_id AND event.status = 'approved'
    )
  );

CREATE POLICY "Users update RSVP responses for approved events"
  ON public.user_event_responses FOR UPDATE TO authenticated
  USING (user_id = (SELECT auth.uid()))
  WITH CHECK (
    user_id = (SELECT auth.uid())
    AND status IN ('interested', 'going')
    AND EXISTS (
      SELECT 1
      FROM public.organizer_events AS event
      WHERE event.id = event_id AND event.status = 'approved'
    )
  );

CREATE POLICY "Users delete their own event responses"
  ON public.user_event_responses FOR DELETE TO authenticated
  USING (user_id = (SELECT auth.uid()));

-- Defaults awarded by organizer-created content are server-owned. Admins may
-- still adjust them during review, but organizers cannot bypass the UI with a
-- direct REST request.
CREATE OR REPLACE FUNCTION public.enforce_organizer_event_insert_defaults()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF auth.uid() = NEW.organizer_user_id
    AND NOT public.has_role(auth.uid(), 'admin')
  THEN
    NEW.xp_bonus = 50;
    NEW.qc_bonus = 5;
    NEW.interested_count = 0;
    NEW.going_count = 0;
    NEW.attendee_count = 0;
    NEW.reviewed_by = NULL;
    NEW.reviewed_at = NULL;
    NEW.rejection_reason = NULL;
    NEW.moderation_message = NULL;
    NEW.review_previous_snapshot = NULL;
    NEW.review_requested_at = CASE WHEN NEW.status = 'pending' THEN now() ELSE NULL END;
    IF NEW.status NOT IN ('draft', 'pending') THEN
      NEW.status = 'pending';
      NEW.review_requested_at = now();
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.enforce_organizer_event_insert_defaults()
  FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS organizer_events_enforce_insert_defaults
  ON public.organizer_events;
CREATE TRIGGER organizer_events_enforce_insert_defaults
  BEFORE INSERT ON public.organizer_events
  FOR EACH ROW EXECUTE FUNCTION public.enforce_organizer_event_insert_defaults();

CREATE OR REPLACE FUNCTION public.force_organizer_event_review_on_owner_update()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF auth.uid() = OLD.organizer_user_id
    AND NOT public.has_role(auth.uid(), 'admin')
  THEN
    IF OLD.status IN ('approved', 'rejected')
      AND OLD.review_previous_snapshot IS NULL
    THEN
      NEW.review_previous_snapshot = jsonb_build_object(
        'title', OLD.title,
        'venue_name', OLD.venue_name,
        'venue_address', OLD.venue_address,
        'venue_latitude', OLD.venue_latitude,
        'venue_longitude', OLD.venue_longitude,
        'category', OLD.category,
        'date_label', OLD.date_label,
        'end_date_label', OLD.end_date_label,
        'time_label', OLD.time_label,
        'end_time_label', OLD.end_time_label,
        'starts_at', OLD.starts_at,
        'ends_at', OLD.ends_at,
        'description', OLD.description,
        'is_free', OLD.is_free,
        'image_url', OLD.image_url
      );
    ELSE
      NEW.review_previous_snapshot = OLD.review_previous_snapshot;
    END IF;

    NEW.organizer_user_id = OLD.organizer_user_id;
    NEW.xp_bonus = OLD.xp_bonus;
    NEW.qc_bonus = OLD.qc_bonus;
    NEW.interested_count = OLD.interested_count;
    NEW.going_count = OLD.going_count;
    NEW.attendee_count = OLD.attendee_count;
    NEW.created_at = OLD.created_at;
    NEW.moderation_message = OLD.moderation_message;
    NEW.status = 'pending';
    NEW.review_requested_at = now();
    NEW.reviewed_at = NULL;
    NEW.reviewed_by = NULL;
    NEW.rejection_reason = NULL;
  END IF;

  RETURN NEW;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.force_organizer_event_review_on_owner_update()
  FROM PUBLIC, anon, authenticated;

DROP TRIGGER IF EXISTS organizer_events_force_review_on_owner_update
  ON public.organizer_events;
CREATE TRIGGER organizer_events_force_review_on_owner_update
  BEFORE UPDATE ON public.organizer_events
  FOR EACH ROW EXECUTE FUNCTION public.force_organizer_event_review_on_owner_update();

