-- A university contributes to rankings only after its student email has been
-- verified. Pending self-declarations remain usable profile state but earn no
-- campus rank or podium badge.
CREATE OR REPLACE FUNCTION public.university_leaderboard_by_city(_city_key text)
RETURNS TABLE (
  university_id text,
  name text,
  short_name text,
  city_key text,
  total_xp bigint,
  member_count bigint,
  rank integer
)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  WITH scores AS (
    SELECT
      university.id AS university_id,
      university.name,
      university.short_name,
      university.city_key,
      COALESCE(SUM(profile.total_xp), 0)::bigint AS total_xp,
      COUNT(membership.user_id)::bigint AS member_count
    FROM public.universities AS university
    LEFT JOIN public.user_university_memberships AS membership
      ON membership.university_id = university.id
      AND membership.status = 'verified'
    LEFT JOIN public.profiles AS profile ON profile.id = membership.user_id
    WHERE university.city_key = _city_key
    GROUP BY university.id, university.name, university.short_name, university.city_key
  )
  SELECT
    scores.university_id,
    scores.name,
    scores.short_name,
    scores.city_key,
    scores.total_xp,
    scores.member_count,
    ROW_NUMBER() OVER (
      ORDER BY scores.total_xp DESC, scores.member_count DESC, scores.name ASC
    )::integer AS rank
  FROM scores
  ORDER BY rank ASC, scores.name ASC;
$$;

REVOKE EXECUTE ON FUNCTION public.university_leaderboard_by_city(text)
  FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.university_leaderboard_by_city(text)
  TO authenticated;

CREATE OR REPLACE FUNCTION public.get_university_profile_summary(_university_id text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  _university public.universities%ROWTYPE;
  _member_count bigint := 0;
  _total_xp bigint := 0;
  _current_rank integer := 0;
  _ranking_history jsonb := '[]'::jsonb;
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
  END IF;

  SELECT * INTO _university
  FROM public.universities
  WHERE id = _university_id;

  IF _university.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'unknown_university');
  END IF;

  SELECT COUNT(membership.user_id)::bigint, COALESCE(SUM(profile.total_xp), 0)::bigint
  INTO _member_count, _total_xp
  FROM public.user_university_memberships AS membership
  LEFT JOIN public.profiles AS profile ON profile.id = membership.user_id
  WHERE membership.university_id = _university.id
    AND membership.status = 'verified';

  WITH scores AS (
    SELECT
      university.id AS university_id,
      COALESCE(SUM(profile.total_xp), 0)::bigint AS total_xp,
      COUNT(membership.user_id)::bigint AS member_count
    FROM public.universities AS university
    LEFT JOIN public.user_university_memberships AS membership
      ON membership.university_id = university.id
      AND membership.status = 'verified'
    LEFT JOIN public.profiles AS profile ON profile.id = membership.user_id
    WHERE university.city_key = _university.city_key
    GROUP BY university.id
  ), ranked AS (
    SELECT university_id,
      ROW_NUMBER() OVER (
        ORDER BY total_xp DESC, member_count DESC, university_id ASC
      )::integer AS rank
    FROM scores
  )
  SELECT rank INTO _current_rank FROM ranked WHERE university_id = _university.id;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'academic_year', season.academic_year,
        'finalized_at', season.finalized_at,
        'member_count', entry.member_count,
        'rank', entry.rank,
        'total_xp', entry.total_xp
      ) ORDER BY season.academic_year DESC, entry.rank ASC
    ),
    '[]'::jsonb
  ) INTO _ranking_history
  FROM public.university_leaderboard_season_entries AS entry
  JOIN public.university_leaderboard_seasons AS season ON season.id = entry.season_id
  WHERE entry.university_id = _university.id AND entry.rank IN (1, 2, 3);

  RETURN jsonb_build_object(
    'success', true,
    'active_member_count', _member_count,
    'city_key', _university.city_key,
    'current_rank', COALESCE(_current_rank, 0),
    'ranking_history', _ranking_history,
    'total_xp', _total_xp,
    'university_id', _university.id,
    'university_name', _university.name,
    'university_short_name', _university.short_name
  );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.get_university_profile_summary(text)
  FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.get_university_profile_summary(text)
  TO authenticated;

CREATE OR REPLACE FUNCTION public.finalize_university_leaderboard_season(
  _academic_year text,
  _city_key text
)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, auth
AS $$
DECLARE
  _uid uuid := auth.uid();
  _season_id uuid;
  _ranked_universities integer := 0;
  _awarded_users integer := 0;
BEGIN
  IF _uid IS NULL OR NOT public.has_role(_uid, 'admin') THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
  END IF;

  IF _academic_year !~ '^20[0-9]{2}/20[0-9]{2}$' OR _city_key NOT IN ('leuven', 'lublin') THEN
    RETURN jsonb_build_object('success', false, 'error', 'invalid_season');
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.university_leaderboard_seasons
    WHERE academic_year = _academic_year AND city_key = _city_key
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'season_already_finalized');
  END IF;

  INSERT INTO public.university_leaderboard_seasons (academic_year, city_key, finalized_by)
  VALUES (_academic_year, _city_key, _uid)
  RETURNING id INTO _season_id;

  WITH scores AS (
    SELECT
      university.id AS university_id,
      COALESCE(SUM(profile.total_xp), 0)::bigint AS total_xp,
      COUNT(membership.user_id)::bigint AS member_count
    FROM public.universities AS university
    JOIN public.user_university_memberships AS membership
      ON membership.university_id = university.id
      AND membership.status = 'verified'
    JOIN public.profiles AS profile ON profile.id = membership.user_id
    WHERE university.city_key = _city_key
    GROUP BY university.id
    HAVING COALESCE(SUM(profile.total_xp), 0) > 0
  ), ranked AS (
    SELECT university_id, total_xp, member_count,
      ROW_NUMBER() OVER (
        ORDER BY total_xp DESC, member_count DESC, university_id ASC
      )::integer AS rank
    FROM scores
  )
  INSERT INTO public.university_leaderboard_season_entries (
    season_id, university_id, rank, total_xp, member_count
  )
  SELECT _season_id, university_id, rank, total_xp, member_count FROM ranked;

  GET DIAGNOSTICS _ranked_universities = ROW_COUNT;

  INSERT INTO public.user_university_leaderboard_awards (
    user_id, season_id, university_id, rank
  )
  SELECT membership.user_id, _season_id, entry.university_id, entry.rank
  FROM public.university_leaderboard_season_entries AS entry
  JOIN public.user_university_memberships AS membership
    ON membership.university_id = entry.university_id
    AND membership.status = 'verified'
  WHERE entry.season_id = _season_id AND entry.rank IN (1, 2, 3);

  GET DIAGNOSTICS _awarded_users = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'academic_year', _academic_year,
    'awarded_users', _awarded_users,
    'ranked_universities', _ranked_universities,
    'season_id', _season_id
  );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.finalize_university_leaderboard_season(text, text)
  FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.finalize_university_leaderboard_season(text, text)
  TO authenticated;

-- Index foreign keys used by current features so deletes, joins, and aggregate
-- profile queries do not degrade as demo data grows.
CREATE INDEX IF NOT EXISTS idx_organizer_announcements_event
  ON public.organizer_announcements (event_id);
CREATE INDEX IF NOT EXISTS idx_organizer_applications_reviewed_by
  ON public.organizer_applications (reviewed_by);
CREATE INDEX IF NOT EXISTS idx_organizer_events_reviewed_by
  ON public.organizer_events (reviewed_by);
CREATE INDEX IF NOT EXISTS idx_organizer_rewards_reviewed_by
  ON public.organizer_rewards (reviewed_by);
CREATE INDEX IF NOT EXISTS idx_quest_completions_quest
  ON public.quest_completions (quest_id);
CREATE INDEX IF NOT EXISTS idx_quests_created_by
  ON public.quests (created_by);
CREATE INDEX IF NOT EXISTS idx_university_email_domains_university
  ON public.university_email_domains (university_id);
CREATE INDEX IF NOT EXISTS idx_university_season_entries_university
  ON public.university_leaderboard_season_entries (university_id);
CREATE INDEX IF NOT EXISTS idx_university_seasons_finalized_by
  ON public.university_leaderboard_seasons (finalized_by);
CREATE INDEX IF NOT EXISTS idx_user_notifications_event
  ON public.user_notifications (event_id) WHERE event_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS idx_university_awards_season
  ON public.user_university_leaderboard_awards (season_id);
CREATE INDEX IF NOT EXISTS idx_university_awards_university
  ON public.user_university_leaderboard_awards (university_id);
CREATE INDEX IF NOT EXISTS idx_university_memberships_university
  ON public.user_university_memberships (university_id);

-- Finish the foreign-key index cleanup, including the retained legacy tables.
CREATE INDEX IF NOT EXISTS idx_profiles_city
  ON public.profiles (city_id);
CREATE INDEX IF NOT EXISTS idx_events_venue
  ON public.events (venue_id);
CREATE INDEX IF NOT EXISTS idx_check_ins_event
  ON public.check_ins (event_id);
CREATE INDEX IF NOT EXISTS idx_redemptions_reward
  ON public.redemptions (reward_id);
CREATE INDEX IF NOT EXISTS idx_redemptions_used_by
  ON public.redemptions (used_by);

-- The unique table constraint already owns the equivalent index.
DROP INDEX IF EXISTS public.idx_xp_transactions_user_source_key;
